        public static void WriteSample()
        {
            List<Sheets.Lfz> allLFZ = [];
            List<Sheets.Slot> allFTS = [];
            List<Sheets.PriceCat> allPriceCat = [];

            //Price Cats
            allPriceCat.Add(new Sheets.PriceCat { Name = "Standard", Price = 3500 });
