            allLFZ.Add(new Sheets.Lfz { Reg = "D-IJKL",Type = "P-17 Stearman",Seats = 1,AutoAssign = false,Interval = 15,PriceCat = 2,AvailTimes = [1,3,5] });
            allLFZ.Add(new Sheets.Lfz { Reg = "D-MNOP",Type = "WT9 Dynamic",Seats = 1,AutoAssign = true,Interval = 15,PriceCat = 1,AvailTimes = [1,2,3,4,5,6] });

            //FTS
            allFTS.Add(new Sheets.Slot { STime = DateTime.Today.AddHours(8),FTime = DateTime.Today.AddHours(9),Length = 15 });
            allFTS.Add(new Sheets.Slot { STime = DateTime.Today.AddHours(9),FTime = DateTime.Today.AddHours(10),Length = 30 });
            allFTS.Add(new Sheets.Slot { STime = DateTime.Today.AddHours(10),FTime = DateTime.Today.AddHours(11),Length = 15 });
            allFTS.Add(new Sheets.Slot { STime = DateTime.Today.AddHours(11),FTime = DateTime.Today.AddHours(12),Length = 30 });
            allFTS.Add(new Sheets.Slot { STime = DateTime.Today.AddHours(12),FTime = DateTime.Today.AddHours(13),Length = 15 });
            allFTS.Add(new Sheets.Slot { STime = DateTime.Today.AddHours(13),FTime = DateTime.Today.AddHours(14),Length = 30 });
            allFTS.Add(new Sheets.Slot { STime = DateTime.Today.AddHours(14),FTime = DateTime.Today.AddHours(15),Length = 15 });

            //Upload
            RData.InsertRange(allPriceCat);
            RData.InsertRange(allLFZ);
            RData.InsertRange(allFTS);

        }

